    "Zilgma": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Zilgma is linked to the Latvian word zilgme. The dictionary records a word-based name formation; it does not identify a particular person as the inventor of the name.",
          "The dictionary gives the following historical record: Riga, second quarter of the twentieth century; calendar 1925. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date. The dates belong to the shared Zilgma / Zilgme entry, not to independently checked records for each spelling."
        ],
        "lv": [
          "Zilgma saistīts ar latviešu vārdu zilgme. Vārdnīca fiksē personvārda darināšanu no valodas vārda, bet nenosauc konkrētu cilvēku par šī vārda izgudrotāju.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Rīga, 20. gadsimta otrais ceturksnis; kalendārā 1925. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu. Datumi attiecas uz kopīgo šķirkli Zilgma / Zilgme, nevis atsevišķi pārbaudītiem katras rakstības ierakstiem."
        ],
        "ru": [
          "Zilgma связано с латышским словом zilgme. Словарь фиксирует образование личного имени от слова языка, но не называет конкретного человека изобретателем имени.",
          "Словарь приводит следующую историческую запись: Рига, вторая четверть XX века; календарь 1925. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени. Даты относятся к общей статье Zilgma / Zilgme, а не к отдельно проверенным записям каждого написания."
        ],
        "lt": [
          "Zilgma siejamas su latvių žodžiu zilgme. Žodynas fiksuoja asmenvardžio darybą iš kalbos žodžio, tačiau nenurodo konkretaus žmogaus kaip šio vardo išradėjo.",
          "Žodynas pateikia tokį istorinį įrašą: Ryga, XX amžiaus antrasis ketvirtis; kalendoriuje 1925. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo. Datos priklauso bendram Zilgma / Zilgme straipsniui, o ne atskirai patikrintiems kiekvienos rašybos įrašams."
        ],
        "et": [
          "Zilgma on seotud läti sõnaga zilgme. Sõnastik dokumenteerib isikunime moodustamist keelesõnast, kuid ei nimeta üht kindlat inimest selle nime loojaks.",
          "Sõnastik annab järgmise ajaloolise kirje: Riia, 20. sajandi teine veerand; kalendris 1925. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist. Daatumid kuuluvad ühise Zilgma / Zilgme artikli juurde, mitte iga kirjapildi eraldi kontrollitud kirjete juurde."
        ]
      }
    },
