          "1964. gada kalendārs, kas pārpublicēts Antana Saļa 1983. gada rakstu krājumā, Krizantas ierindo 25. oktobrī. Tā ir liecība par kalendāra vēsturi, nevis pirmo vārda nesēju vai vārda radīšanu."
